class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        import bisect

        n = len(nums)
        min_diff = float('inf')

        # Maintain a list of values from indices that are at least x indices behind
        values = []

        for i in range(n):
            # Check if there are any valid previous elements (at least x indices before)
            if i >= x:
                # Find insertion point for nums[i]
                pos = bisect.bisect_left(values, nums[i])
                # Check the value at pos (if exists)
                if pos < len(values):
                    min_diff = min(min_diff, abs(nums[i] - values[pos]))
                # Check the value at pos-1 (if exists)
                if pos > 0:
                    min_diff = min(min_diff, abs(nums[i] - values[pos - 1]))

            # Add the value at index i-x to values
            if i >= x:
                bisect.insort(values, nums[i - x])

        return min_diff

