import bisect
from typing import List

class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        n = len(nums)
        min_diff = float('inf')

        # For each position i, we'll find the closest element to nums[i]
        # that is at least x indices away

        # We can use two passes:
        # 1. From left to right: for each i, consider elements at positions <= i-x
        # 2. From right to left: for each i, consider elements at positions >= i+x

        # Left pass: consider elements that are at least x indices before
        left_set = []  # sorted list of elements at positions 0 to i-x

        for i in range(n):
            # Add element at position i-x to left_set (if it exists)
            if i >= x:
                bisect.insort(left_set, nums[i - x])

            # Check if we can form a valid pair with elements in left_set
            if left_set:
                # Find closest element in left_set to nums[i]
                pos = bisect.bisect_left(left_set, nums[i])
                if pos < len(left_set):
                    min_diff = min(min_diff, abs(nums[i] - left_set[pos]))
                if pos > 0:
                    min_diff = min(min_diff, abs(nums[i] - left_set[pos-1]))

        # Right pass: consider elements that are at least x indices after
        right_set = []  # sorted list of elements at positions i+x to n-1

        for i in range(n-1, -1, -1):
            # Add element at position i+x to right_set (if it exists)
            if i + x < n:
                bisect.insort(right_set, nums[i + x])

            # Check if we can form a valid pair with elements in right_set
            if right_set:
                # Find closest element in right_set to nums[i]
                pos = bisect.bisect_left(right_set, nums[i])
                if pos < len(right_set):
                    min_diff = min(min_diff, abs(nums[i] - right_set[pos]))
                if pos > 0:
                    min_diff = min(min_diff, abs(nums[i] - right_set[pos-1]))

        return min_diff
